code_example:
int i = 0;
const int& j = i;

// Case 1: decltype on a name
decltype(i) x;        // x is type int (declared type of i)
decltype(j) y = i;    // y is type const int& (declared type of j)

// Case 2: decltype on an lvalue expression
decltype((i)) z = i;  // (i) is an lvalue expression, not just a name
                        // z is type int& (reference to i's type)

// Example of changing behavior
z = 10; // i is now 10
// x = 5;  // x is a separate int, doesn't affect i
